def find(parent, i):
    if parent[i] == i:
        return i
    parent[i] = find(parent, parent[i])
    return parent[i]

def union(parent, rank, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)

    if rootX != rootY:
        if rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        elif rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def is_tree(graph, n):
    parent = list(range(n))
    rank = [0] * n

    for u, v in graph:
        rootU = find(parent, u)
        rootV = find(parent, v)

        if rootU == rootV:
            return False

        union(parent, rank, rootU, rootV)

    # Check if there is exactly one component (tree)
    root_set = set()
    for i in range(n):
        root_set.add(find(parent, i))

    return len(root_set) == 1

